    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
        // TODO add your handling code here:
        int baris = jTable1.getSelectedRow();
        
        if (baris == -1){
            return;
        }
        String nim = txtNim.getText();
        String nama = txtNama.getText();
        String jurusan = txtJurusan.getText();

        jTable1.setValueAt(nim, baris, 0);
        jTable1.setValueAt(nama, baris, 1);
        jTable1.setValueAt(jurusan, baris, 2);

    }//GEN-LAST:event_jButton2ActionPerformed

    private void jTable1MouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_jTable1MouseClicked
        // TODO add your handling code here:
        int baris = jTable1.getSelectedRow();
        
        txtNim.setText(jTable1.getValueAt(baris, 0).toString());
        txtNama.setText(jTable1.getValueAt(baris,1).toString());
        txtJurusan.setText(jTable1.getValueAt(baris, 2).toString());
    }//GEN-LAST:event_jTable1MouseClicked

